            % vset1 = vertexset(NonZeros(`B⁰` IndicatorVector(eset1))) - {v}
            vset1 = setdiff(NonZeros(B0 * indicator(eset1, M.n_edges())), [v]);
            % eset2 = { e for e ∈ nes if `∂¹`_e,f `∂⁰`_v,e = 1 }
            NeighborVerticesInFaceset_4 = [];
            range_2 = nes;
            for index_2 = 1:length(range_2)
                e = range_2(index_2);
                if dee1(e, f) * dee0(v, e) == 1
                    NeighborVerticesInFaceset_4 = [NeighborVerticesInFaceset_4; e];
                end
            end
            eset2 = NeighborVerticesInFaceset_4;
            % vset2 = vertexset(NonZeros(`B⁰` IndicatorVector(eset2))) - {v}
            vset2 = setdiff(NonZeros(B0 * indicator(eset2, M.n_edges())), [v]);
            tuple = [vset1(1),vset2(1)];
            ret_3 = tuple(1);
            ret_4 = tuple(2);
        end
        function [ret_5] = NextVerticeInFace(f, v)
            assert(numel(f) == 1);
            assert(numel(v) == 1);
            assert( ismember(v, V) );
            assert( ismember(f, F) );
            % eset = { e for e ∈ Edges(f) if `∂¹`_e,f `∂⁰`_v,e = -1}
            NextVerticeInFaceset_0 = [];
            range_3 = Edges_1(f);
            for index_3 = 1:length(range_3)
                e = range_3(index_3);
                if dee1(e, f) * dee0(v, e) == -1
                    NextVerticeInFaceset_0 = [NextVerticeInFaceset_0; e];
                end
            end
            eset = NextVerticeInFaceset_0;
            % vset = Vertices(eset) - {v}
            vset = setdiff(Vertices_3(eset), [v]);
            ret_5 = vset(1);
        end
        function [ret_6, ret_7, ret_8] = OrientedVertices(f)
            assert(numel(f) == 1);
            assert( ismember(f, F) );
            % vs = Vertices(f)
            vs = Vertices_0(f);
            [i, j] = NeighborVerticesInFace(f, vs(1));
            tuple_1 = [vs(1),i,j];
            ret_6 = tuple_1(1);
            ret_7 = tuple_1(2);
            ret_8 = tuple_1(3);
        end
        function [ret_9, ret_10, ret_11, ret_12] = Diamond(e)
            assert(numel(e) == 1);
            assert( ismember(e, E) );
            tuple_2 = [Vertices_2(e),[e],Faces_1(e),[]];
            ret_9 = tuple_2(1);
            ret_10 = tuple_2(2);
            ret_11 = tuple_2(3);
            ret_12 = tuple_2(4);
        end
        function [ret_13, ret_14] = OrientedOppositeFaces(i, j)
            assert(numel(i) == 1);
            assert(numel(j) == 1);
            assert( ismember(i, V) );
            assert( ismember(j, V) );
            % e = EdgeIndex(i, j)
            e = EdgeIndex(i, j);
            % fset = Faces(e)
            fset = Faces_1(e);
            % firf = { f for f ∈ fset if `∂¹`_e,f `∂⁰`_i,e = -1 }
            OrientedOppositeFacesset_0 = [];
            range_4 = fset;
            for index_4 = 1:length(range_4)
                f = range_4(index_4);
                if dee1(e, f) * dee0(i, e) == -1
                    OrientedOppositeFacesset_0 = [OrientedOppositeFacesset_0; f];
                end
            end
            firf = OrientedOppositeFacesset_0;
            % secf = fset - firf
            secf = setdiff(fset, firf);
            tuple_3 = [firf(1),secf(1)];
            ret_13 = tuple_3(1);
            ret_14 = tuple_3(2);
        end
        function [ret_15, ret_16] = OppositeFaces(e)
            assert(numel(e) == 1);
            assert( ismember(e, E) );
            % fset = Faces(e)
            fset = Faces_1(e);
            % firf = { f for f ∈ fset if `∂¹`_e,f = 1 }
            OppositeFacesset_0 = [];
            range_5 = fset;
            for index_5 = 1:length(range_5)
                f = range_5(index_5);
                if dee1(e, f) == 1
                    OppositeFacesset_0 = [OppositeFacesset_0; f];
                end
            end
            firf = OppositeFacesset_0;
            % secf = { f for f ∈ fset if `∂¹`_e,f = -1 }
            OppositeFacesset_1 = [];
            range_6 = fset;
            for index_6 = 1:length(range_6)
                f = range_6(index_6);
                if dee1(e, f) == -1
                    OppositeFacesset_1 = [OppositeFacesset_1; f];
                end
            end
            secf = OppositeFacesset_1;
            tuple_4 = [firf(1),secf(1)];
            ret_15 = tuple_4(1);
            ret_16 = tuple_4(2);
        end
        function [ret_17, ret_18] = OppositeVertices(e)
            assert(numel(e) == 1);
            assert( ismember(e, E) );
            [firf, secf] = OppositeFaces(e);
            % firv = Vertices(firf) \ Vertices(e)
            firv = setdiff(Vertices_0(firf), Vertices_2(e));
            % secv = Vertices(secf) \ Vertices(e)
            secv = setdiff(Vertices_0(secf), Vertices_2(e));
            tuple_5 = [firv(1),secv(1)];
            ret_17 = tuple_5(1);
            ret_18 = tuple_5(2);
        end
        function [ret_19, ret_20] = OppositeVertices_0(i, j)
            assert(numel(i) == 1);
            assert(numel(j) == 1);
            assert( ismember(i, V) );
            assert( ismember(j, V) );
            [firf, secf] = OrientedOppositeFaces(i, j);
            % firv = Vertices(firf) \ {i, j}
            firv = setdiff(Vertices_0(firf), [i, j]);
            % secv = Vertices(secf) \ {i, j}
            secv = setdiff(Vertices_0(secf), [i, j]);
            tuple_6 = [firv(1),secv(1)];
            ret_19 = tuple_6(1);
            ret_20 = tuple_6(2);
        end
        function [ret_21] = FaceIndex(i, j, k)
            assert(numel(i) == 1);
            assert(numel(j) == 1);
            assert(numel(k) == 1);
            assert( ismember(i, V) );
            assert( ismember(j, V) );
            assert( ismember(k, V) );
            % ufv = `B¹`ᵀ `B⁰`ᵀ
            ufv = B1' * B0';
            % iface = faceset(NonZeros(ufv  IndicatorVector({i})))
            iface = NonZeros(ufv * indicator([i], M.n_vertices()));
            % jface = faceset(NonZeros(ufv  IndicatorVector({j})))
            jface = NonZeros(ufv * indicator([j], M.n_vertices()));
            % kface = faceset(NonZeros(ufv IndicatorVector({k})))
            kface = NonZeros(ufv * indicator([k], M.n_vertices()));
            % fset = iface ∩ jface ∩ kface
            fset = intersect(iface, intersect(jface, kface));
            ret_21 = fset(1);
        end
        function [ret_22, ret_23] = OrientedVertices_0(i, j, k)
            assert(numel(i) == 1);
            assert(numel(j) == 1);
            assert(numel(k) == 1);
            assert( ismember(i, V) );
            assert( ismember(j, V) );
            assert( ismember(k, V) );
            % f = FaceIndex(i, j, k)
            f = FaceIndex(i, j, k);
            tuple_7 = NeighborVerticesInFace(f, i);
            ret_22 = tuple_7(1);
            ret_23 = tuple_7(2);
        end
        output.V = V;
        output.E = E;
        output.F = F;
        output.dee0 = dee0;
        output.dee1 = dee1;
        output.B0 = B0;
        output.B1 = B1;
        output.B0T = B0T;
        output.B1T = B1T;
        output.VertexOneRing = @VertexOneRing;
        output.VertexOneRing_0 = @VertexOneRing_0;
        output.EdgeIndex = @EdgeIndex;
        output.NeighborVerticesInFace = @NeighborVerticesInFace;
        output.NextVerticeInFace = @NextVerticeInFace;
        output.OrientedVertices = @OrientedVertices;
        output.Diamond = @Diamond;
        output.OrientedOppositeFaces = @OrientedOppositeFaces;
        output.OppositeFaces = @OppositeFaces;
        output.OppositeVertices = @OppositeVertices;
        output.OppositeVertices_0 = @OppositeVertices_0;
        output.FaceIndex = @FaceIndex;
        output.OrientedVertices_0 = @OrientedVertices_0;
        output.M = M;
    end
    Neighborhoods_ = Neighborhoods(M);
    VertexOneRing = @Neighborhoods_.VertexOneRing;
    VertexOneRing_0 = @Neighborhoods_.VertexOneRing_0;
    function [ret] = y(i)
        assert(numel(i) == 1);
        assert( ismember(i, V) );

        sum_0 = zeros(3,1);
        range = VertexOneRing(i);
        for index = 1:length(range)
            j = range(index);
            sum_0 = sum_0 + x(j,:)';
        end
        ret = sum_0;
    end

    output.V = V;
    output.E = E;
    output.F = F;
    output.y = @y;
    output.M = M;    
    output.x = x;
end

